      if(!node||node.cmSignature!==signature){const holder=document.createElement('div');holder.innerHTML=this.conversationMarkup(row,row.id===selected);const replacement=holder.firstElementChild;replacement.cmSignature=signature;if(node)node.replaceWith(replacement);node=replacement;}
