    try{const wanted=Math.max(20,state.items.length),rows=[];let cursor=null,data;do{data=await this.api.get('/messages/conversations',{cursor,limit:Math.min(50,wanted-rows.length)});if(state!==this.inbox||state.token!==this.routeToken||!this.alive())return;for(const row of data.items||[])if(!rows.some(item=>item.id===row.id))rows.push(row);cursor=data.nextCursor;}while(data.hasMore&&cursor&&rows.length<wanted);state.items=this.readAwareInboxItems(rows,ticket);state.cursor=data.nextCursor;state.hasMore=!!data.hasMore;state.loaded=true;state.error=null;this.applyInboxUnread(data.unreadCount,ticket);this.renderInbox();}catch{}finally{state.refreshing=false;}
