  noteMore(trigger) {const note=this.detail?.note;if(!note)return;const own=String(note.author.id)===this.accountId;this.showContextMenu(trigger||this.dialog?.querySelector('[data-cm="note-more"]'),'笔记操作',own?`<a href="#community/edit/${escape(note.id)}" data-cm="nav" class="cm-context-action" role="menuitem" tabindex="-1">${icon('edit')}<span>编辑笔记</span></a><button class="cm-context-action cm-context-danger" data-cm="note-delete" data-id="${escape(note.id)}" role="menuitem" tabindex="-1">${icon('trash')}<span>删除笔记</span></button>`:`<button class="cm-context-action" data-cm="report-note" data-id="${escape(note.id)}" role="menuitem" tabindex="-1"><span>举报</span></button>`);}
