  readEditor() {const draft=this.editor,form=this.page()?.querySelector('[data-cm-form="publish"]');if(!draft||!form)return draft;draft.title=form.elements.title.value;draft.body=form.elements.body.value;draft.category=form.elements.category.value;draft.topics=form.elements.topics.value.split(/[，,]/).map(value=>value.trim().replace(/^#+/,'' )).filter(Boolean);return draft;}
  scheduleSave() {if(!this.editor||this.suppressSave)return;clearTimeout(this.saveTimer);this.page()?.querySelector('.cm-save-status')?.replaceChildren(document.createTextNode('正在保存本机草稿…'));this.saveTimer=setTimeout(()=>this.saveEditor().catch(()=>{}),600);}
  async saveEditor(explicit=false) {
    if(this.suppressSave)return;clearTimeout(this.saveTimer);const draft=this.readEditor();if(!draft)return;const {publishing,...persistentDraft}=draft;const snapshot={...persistentDraft,assets:draft.assets.map(({localUrl,controller,progress,...asset})=>({...asset,status:asset.status==='uploading'?'pending':asset.status}))};
    try{await this.drafts.save(snapshot);if(this.editor===draft){this.page()?.querySelector('.cm-save-status')?.replaceChildren(document.createTextNode('已保存到本机 · '+new Date().toLocaleTimeString('zh-CN',{hour:'2-digit',minute:'2-digit'})));const status=this.page()?.querySelector('.cm-editor-status');if(status)status.textContent=`文字已保存 · ${draft.assets.filter(asset=>asset.file).length} 份本机素材 · ${draft.assets.filter(asset=>asset.status==='ready').length} 份已上传`;if(explicit)this.toast('草稿已保存，仅当前账号在这台设备可见');}return snapshot;}catch(error){if(this.editor===draft){this.page()?.querySelector('.cm-save-status')?.replaceChildren(document.createTextNode('本机保存失败，请勿关闭页面'));const banner=this.page()?.querySelector('.cm-editor-error');if(banner)banner.textContent='本机存储容量不足或不可用。文字与素材尚未确认保存，请释放空间后重试。';}if(explicit)this.error(error);throw error;}
  }
  async leaveEditor() {if(!this.editor)return;const draft=this.editor;clearTimeout(this.saveTimer);await this.saveEditor().catch(()=>{});for(const asset of draft.assets||[]){asset.controller?.abort();if(asset.status==='uploading')asset.status='pending';if(asset.localUrl){URL.revokeObjectURL(asset.localUrl);this.urls.delete(asset.localUrl);delete asset.localUrl;}}this.editor=null;}
  async validateDraftMedia(draft) {for(const asset of draft.assets){if(!asset.media)continue;try{const response=await this.api.get('/media/'+encodeURIComponent(asset.media.id)+'/metadata');if(this.editor!==draft||!this.alive())return;asset.media=response.media||response;if(asset.media.status!=='ready')throw new Error('\u7d20\u6750\u5df2\u5931\u6548\uff0c\u8bf7\u91cd\u65b0\u4e0a\u4f20');asset.status='ready';asset.error='';}catch(error){if(this.editor!==draft)return;asset.status=asset.file?'pending':'failed';asset.error=asset.file?'素材已失效，可重新上传':'素材已失效，请重新选择原文件';if(error.status===401)this.error(error);}}if(this.editor===draft)this.renderAssets();}
  renderAssets() {const draft=this.editor,container=this.page()?.querySelector('.cm-assets');if(!draft||!container)return;container.innerHTML=draft.assets.map((asset,index)=>{const url=asset.localUrl||communityMediaUrl(asset.media,draft.status==='hidden'),video=asset.role==='video';return `<article class="cm-asset" data-asset="${escape(asset.key)}"><div class="cm-asset-preview">${url?video?`<video src="${escape(url)}" muted preload="metadata" playsinline></video>`:`<img src="${escape(url)}" alt="${escape(asset.name||'素材 '+(index+1))}">`:`<span>${icon(video?'play':'image')}</span>`}${asset.role==='video-cover'?'<span class="cm-asset-label">视频封面</span>':asset.isCover?'<span class="cm-asset-label">封面</span>':''}<button type="button" class="cm-asset-remove cm-icon-button" data-cm="asset-remove" data-key="${escape(asset.key)}" aria-label="移除素材">${icon('close')}</button></div><div class="cm-asset-info"><strong>${escape(asset.name||'已上传素材')}</strong><span>${asset.file?(asset.file.size/1024/1024).toFixed(1)+' MB · ':''}${asset.status==='ready'?'已上传':asset.status==='uploading'?'上传中 '+(asset.progress||0)+'%':asset.status==='failed'?'上传失败':'等待上传'}</span>${asset.status==='uploading'?`<progress max="100" value="${asset.progress||0}" aria-label="素材上传进度"></progress>`:''}${asset.error?`<p class="cm-asset-error">${escape(asset.error)}</p>`:''}<div class="cm-asset-actions">${asset.role==='image'?`<button type="button" data-cm="asset-left" data-key="${escape(asset.key)}" ${index===0?'disabled':''} aria-label="向前移动">←</button><button type="button" data-cm="asset-right" data-key="${escape(asset.key)}" ${index===draft.assets.length-1?'disabled':''} aria-label="向后移动">→</button><button type="button" data-cm="asset-cover" data-key="${escape(asset.key)}" ${asset.isCover?'disabled':''}>设为封面</button>`:''}${['pending','failed'].includes(asset.status)&&asset.file?`<button type="button" data-cm="asset-retry" data-key="${escape(asset.key)}">${icon('refresh')} 重试上传</button>`:''}</div></div></article>`;}).join('');const input=this.page().querySelector('#cm-files');if(input)input.disabled=draft.type==='video'?draft.assets.some(asset=>asset.role==='video'):draft.assets.filter(asset=>asset.role==='image').length>=9;}
  async selectFiles(files,cover=false) {const draft=this.editor;if(!draft)return;const incoming=[...files];for(const file of incoming){if(this.editor!==draft)return;const video=file.type==='video/mp4';if(cover&&video||!['image/jpeg','image/png','image/webp','video/mp4'].includes(file.type)){this.toast('请选择 JPEG、PNG、WebP 图片或 MP4 视频',true);continue;}if(file.size>(video?50:10)*1024*1024){this.toast(`${file.name} 超过${video?'50':'10'} MB，请重新选择`,true);continue;}if(!cover&&draft.type==='video'&&!video||!cover&&draft.type!=='video'&&video){this.toast('请先切换到相应的笔记类型',true);continue;}if(!cover&&draft.type!=='video'&&draft.assets.filter(asset=>asset.role==='image').length>=9){this.toast('一篇笔记最多添加 9 张图片',true);break;}if(video&&draft.assets.some(asset=>asset.role==='video')){this.toast('一篇笔记只能添加一个视频',true);continue;}
      if(cover){const old=draft.assets.find(asset=>asset.role==='video-cover');if(old)this.removeAsset(old.key);}
      const role=cover?'video-cover':video?'video':'image',asset={key:communityId(),name:file.name,file,role,status:'pending',isCover:cover||role==='image'&&!draft.assets.some(row=>row.isCover)};asset.localUrl=URL.createObjectURL(file);this.urls.add(asset.localUrl);draft.assets.push(asset);this.renderAssets();this.scheduleSave();this.uploadAsset(asset.key);
    }}
  async uploadAsset(key) {const draft=this.editor,asset=draft?.assets.find(row=>row.key===key);if(!asset?.file||asset.status==='uploading')return;asset.status='uploading';asset.error='';asset.progress=0;asset.controller=this.controller();this.renderAssets();try{const media=await this.api.upload(asset.file,{signal:asset.controller.signal,onProgress:progress=>{if(this.editor!==draft)return;asset.progress=progress;const element=this.page()?.querySelector(`[data-asset="${CSS.escape(key)}"]`);const bar=element?.querySelector('progress');if(bar)bar.value=progress;const label=element?.querySelector('.cm-asset-info>span');if(label)label.textContent=`上传中 ${progress}%`;}});if(!draft.assets.includes(asset)||!this.alive())return;asset.media=media;asset.status='ready';asset.error='';}catch(error){asset.status='failed';asset.error=abortError(error)?'上传已暂停，可重试':error.message;if(error.status===401)this.error(error);}finally{this.controllers.delete(asset.controller);delete asset.controller;if(this.editor===draft){this.renderAssets();this.scheduleSave();}}}
