  editorError(message) {const element=this.page()?.querySelector('.cm-editor-error');if(element)element.textContent=message||'';if(message)element?.scrollIntoView({block:'nearest'});}
  validateEditor(draft) {if(!draft.title.trim())return '请填写标题';if(draft.title.length>40)return '标题最多 40 字';if(draft.body.length>2000)return '正文最多 2000 字';if(!categories.some(([id])=>id&&id===draft.category))return '请选择一个主分类';if(draft.topics.length>5||draft.topics.some(topic=>topic.length>20))return '最多填写 5 个话题，每个话题最多 20 字';if(!draft.assets.length&&!draft.body.trim())return '纯文字笔记需要填写正文';if(draft.type==='video'&&!draft.assets.some(asset=>asset.role==='video'))return '请选择一个短视频';if(draft.type==='video'&&!draft.assets.some(asset=>asset.role==='video-cover'))return '请选择一张视频封面';if(draft.assets.some(asset=>asset.status!=='ready'||!asset.media))return '素材尚未全部上传成功，请完成上传或重试后发布';return '';}
