    if(!useRemote){draft.version=note.version;draft.mutationId=communityId();this.closeAux();this.conflict=null;await this.saveEditor();this.editorError('已选择保留本机修改，后续保存将覆盖刚才展示的线上版本。请确认内容后点击“保存修改”。');return;}
